formulas.expression:
IF(
    {!Var_PreviousOppPrincipalPaidPercentage} >= 100,
    /* Term Complete */
    DATE(
        YEAR({!Var_100PaidInDate})+1,
        MONTH({!Var_100PaidInDate}),
        DAY({!Var_100PaidInDate})
    ),
    /* 10-50% */
    IF(
        {!Var_PaymentFrequency} = "Weekly",
        {!Var_FundDateForActual} + ((VALUE({!Var_ActualMCATerm}) *7 ) * 1/10),
        {!Var_FundDateForActual} + (((VALUE({!Var_ActualMCATerm}) /5) *7) *5/10)
    )
)

IF(
    /* Term Complete */
    OR(
        {!Var_PreviousOppPrincipalPaidPercentage} >= 100,
        {!Var_InputStatus} = "Term Complete"
    ), "Term Complete",
    IF(
        /* Pre-EDR */
        OR(
            YEAR({!Var_EligibilityDate}) > YEAR({!$Flow.CurrentDate}),
            AND(
                MONTH({!Var_EligibilityDate}) > MONTH({!$Flow.CurrentDate}),
                YEAR({!Var_EligibilityDate}) = YEAR({!$Flow.CurrentDate})
            )
        ), "Pre-EDR",
        IF(
            /* EDR */
            OR(
                AND(
                    YEAR({!Var_EligibilityDate}) = YEAR({!$Flow.CurrentDate}),
                    MONTH({!Var_EligibilityDate}) = MONTH({!$Flow.CurrentDate})
                ),
                {!Var_InputStatus} = "EDR"
            ), "EDR", "Trailing EDR"
        )
    )
)
